package com.taller.portal.controller;
import com.taller.portal.dto.StatusDtos.*; import com.taller.portal.service.StatusFacade; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
/** Endpoints REST del catálogo Status. */ @RestController @RequestMapping("/api/status") public class StatusController { private final StatusFacade facade; public StatusController(StatusFacade f){facade=f;} @GetMapping public Pagina listar(@RequestParam(defaultValue="0")int pagina,@RequestParam(defaultValue="10")int tamanio,@RequestParam(defaultValue="id")String orden,@RequestParam(defaultValue="asc")String direccion,Authentication a){return facade.listar(pagina,tamanio,orden,direccion,a);}@GetMapping("/{id}") public Fila uno(@PathVariable Long id,Authentication a){return facade.uno(id,a);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Fila crear(@Valid @RequestBody Entrada e,Authentication a){return facade.crear(e,a);}@PutMapping("/{id}") public Fila actualizar(@PathVariable Long id,@Valid @RequestBody Entrada e,Authentication a){return facade.actualizar(id,e,a);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void eliminar(@PathVariable Long id,Authentication a){facade.eliminar(id,a);} }
